"""Changelog and version files from Conventional Commit messages. See task.md."""

from __future__ import annotations

import os
import re


class CommitError(ValueError):
    """Raised when `previous_version` is not a valid `X.Y.Z` version."""


_VERSION = re.compile(r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)")
_HEADER = re.compile(r"([a-z]+)(?:\(([^()]*)\))?(!?):(.*)", re.DOTALL)
_BREAKING = ("BREAKING CHANGE:", "BREAKING-CHANGE:")


def _parse(message):
    subject, sep, body = message.partition("\n\n")
    subject = subject.strip()
    if "\n" in subject or "\r" in subject:
        return None
    m = _HEADER.fullmatch(subject)
    if m is None:
        return None
    type_, scope, bang, description = m.groups()
    description = description.strip()
    if not description:
        return None
    scope = (scope or "").strip() or None
    breaking = bool(bang)
    if not breaking and sep:
        breaking = any(
            line.strip().startswith(_BREAKING) for line in re.split(r"\r\n|\r|\n", body)
        )
    return type_, scope, description, breaking


def build(commits: list[str], previous_version: str, out_dir: str) -> None:
    """Write `<out_dir>/CHANGELOG.md` and `<out_dir>/version.txt`."""
    m = _VERSION.fullmatch(previous_version) if isinstance(previous_version, str) else None
    if m is None:
        raise CommitError(f"invalid version: {previous_version!r}")
    major, minor, patch = (int(p) for p in m.groups())

    sections = {"breaking": set(), "feat": set(), "fix": set(), "perf": set()}
    has_breaking = has_feat = has_fix = False
    for message in commits:
        parsed = _parse(message)
        if parsed is None:
            continue
        type_, scope, description, breaking = parsed
        key = "breaking" if breaking else type_
        if key in sections:
            sections[key].add((scope is None, scope or "", description))
        if breaking:
            has_breaking = True
        elif type_ == "feat":
            has_feat = True
        elif type_ in ("fix", "perf"):
            has_fix = True

    if has_breaking:
        version = f"{major + 1}.0.0"
    elif has_feat:
        version = f"{major}.{minor + 1}.0"
    elif has_fix:
        version = f"{major}.{minor}.{patch + 1}"
    else:
        version = previous_version

    out = [f"## {version}\n"]
    titles = [
        ("breaking", "Breaking changes"),
        ("feat", "Features"),
        ("fix", "Fixes"),
        ("perf", "Performance"),
    ]
    for key, title in titles:
        entries = sections[key]
        if not entries:
            continue
        lines = []
        for no_scope, scope, description in sorted(entries):
            line = f"- {description}" if no_scope else f"- **{scope}**: {description}"
            if line not in lines:
                lines.append(line)
        out.append(f"\n### {title}\n\n")
        out.append("".join(line + "\n" for line in lines))

    os.makedirs(out_dir, exist_ok=True)
    with open(os.path.join(out_dir, "CHANGELOG.md"), "w", encoding="utf-8", newline="") as f:
        f.write("".join(out))
    with open(os.path.join(out_dir, "version.txt"), "w", encoding="utf-8", newline="") as f:
        f.write(version + "\n")
